package org.apache.lucene.rucene.codec;

import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Collections;
import java.util.Locale;

import org.apache.lucene.codecs.hnsw.FlatFieldVectorsWriter;
import org.apache.lucene.codecs.hnsw.FlatVectorsReader;
import org.apache.lucene.codecs.hnsw.FlatVectorsWriter;
import org.apache.lucene.codecs.lucene104.Lucene104Codec;
import org.apache.lucene.codecs.lucene104.Lucene104ScalarQuantizedVectorsFormat;
import org.apache.lucene.codecs.lucene104.Lucene104ScalarQuantizedVectorsReader;
import org.apache.lucene.index.DocValuesSkipIndexType;
import org.apache.lucene.index.MergeState;
import org.apache.lucene.index.DocValuesType;
import org.apache.lucene.index.FieldInfo;
import org.apache.lucene.index.FieldInfos;
import org.apache.lucene.index.FloatVectorValues;
import org.apache.lucene.index.IndexOptions;
import org.apache.lucene.index.KnnVectorValues;
import org.apache.lucene.index.SegmentInfo;
import org.apache.lucene.index.SegmentReadState;
import org.apache.lucene.index.SegmentWriteState;
import org.apache.lucene.index.VectorEncoding;
import org.apache.lucene.index.VectorSimilarityFunction;
import org.apache.lucene.search.DocIdSetIterator;
import org.apache.lucene.store.FSDirectory;
import org.apache.lucene.store.IOContext;
import org.apache.lucene.util.InfoStream;
import org.apache.lucene.util.Version;
import org.apache.lucene.util.hnsw.CloseableRandomVectorScorerSupplier;
import org.apache.lucene.util.hnsw.RandomVectorScorer;
import org.apache.lucene.util.hnsw.UpdateableRandomVectorScorer;
import org.apache.lucene.util.quantization.QuantizedByteVectorValues.ScalarEncoding;

/**
 * Drives {@code Lucene104ScalarQuantizedVectorsFormat} directly — no
 * {@code IndexWriter}, no indexing chain — so that the {@code .vemq} and
 * {@code .veq} files it writes, and the {@code .vec}/{@code .vemf} files its raw
 * delegate writes, depend on nothing but that format.
 *
 * <p>The vectors of every case are generated by a fixed formula the Rust
 * portability test mirrors exactly, so a byte difference can only come from the
 * quantization, from the centroid, or from the metadata layout.
 *
 * <p>The grid spans the dimensions that change the bytes:
 *
 * <ul>
 *   <li><b>all three symmetric encodings</b> — {@code UNSIGNED_BYTE},
 *       {@code PACKED_NIBBLE} and {@code SEVEN_BIT}. Their wire numbers are 0, 1
 *       and 2 and are <em>not</em> the declaration order a reader might assume,
 *       so a swap between the last two writes a {@code .vemq} Lucene decodes as
 *       the wrong width;
 *   <li><b>all four similarity functions</b> — each is an ordinal in the
 *       metadata, and {@code COSINE} additionally normalises both the vectors
 *       and the centroid before quantizing;
 *   <li><b>dimensions at the packing edges</b> — 1, 3 and 5 are odd, so
 *       {@code PACKED_NIBBLE} pads them to a whole byte; 8 and 16 are exact;
 *   <li><b>dense and sparse fields</b> — a sparse field adds the
 *       {@code DirectMonotonicWriter} ordinal-to-document mapping to the
 *       metadata and moves the vector data offset.
 * </ul>
 *
 * <p>Usage: {@code java ... ScalarQuantizedVectorsFixture <dir> <case>}, where
 * the case is {@code <encoding>_<similarity>_<dim>_<density>}.
 */
public final class ScalarQuantizedVectorsFixture {

  private ScalarQuantizedVectorsFixture() {}

  static final byte[] SEGMENT_ID = new byte[] {
    0x51, 0x56, 0x45, 0x43, 0x54, 0x4f, 0x52, 0x53, 0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07
  };

  static final String FIELD = "vec";
  static final int MAX_DOC = 12;

  /** The vector of document {@code doc}, or {@code null} when it has none. */
  static float[] vectorFor(int doc, int dim, boolean dense) {
    if (!dense && doc % 3 != 0) {
      return null;
    }
    float[] v = new float[dim];
    for (int i = 0; i < dim; i++) {
      // A deterministic spread that is neither monotonic nor symmetric, so the
      // optimized interval search has something to do.
      v[i] = ((doc * 31 + i * 17) % 23) - 11 + (i % 5) * 0.25f;
    }
    return v;
  }

  static ScalarEncoding encodingFor(String name) {
    return switch (name) {
      case "unsignedbyte" -> ScalarEncoding.UNSIGNED_BYTE;
      case "packednibble" -> ScalarEncoding.PACKED_NIBBLE;
      case "sevenbit" -> ScalarEncoding.SEVEN_BIT;
      case "singlebit" -> ScalarEncoding.SINGLE_BIT_QUERY_NIBBLE;
      case "dibit" -> ScalarEncoding.DIBIT_QUERY_NIBBLE;
      default -> throw new IllegalArgumentException("unknown encoding: " + name);
    };
  }

  static VectorSimilarityFunction similarityFor(String name) {
    return switch (name) {
      case "euclidean" -> VectorSimilarityFunction.EUCLIDEAN;
      case "dot" -> VectorSimilarityFunction.DOT_PRODUCT;
      case "cosine" -> VectorSimilarityFunction.COSINE;
      case "mip" -> VectorSimilarityFunction.MAXIMUM_INNER_PRODUCT;
      default -> throw new IllegalArgumentException("unknown similarity: " + name);
    };
  }

  static FieldInfo fieldInfo(int dim, VectorSimilarityFunction similarity) {
    return new FieldInfo(
        FIELD,
        0,
        false,
        true,
        false,
        IndexOptions.NONE,
        DocValuesType.NONE,
        DocValuesSkipIndexType.NONE,
        -1,
        Collections.emptyMap(),
        0, // pointDimensionCount
        0, // pointIndexDimensionCount
        0, // pointNumBytes
        dim,
        VectorEncoding.FLOAT32,
        similarity,
        false,
        false);
  }

  public static void main(String[] args) throws Exception {
    if (args.length != 2) {
      throw new IllegalArgumentException("usage: <dir> <case>");
    }
    Path dir = Paths.get(args[0]);
    String[] parts = args[1].split("_");
    if (parts.length != 4) {
      throw new IllegalArgumentException("case must be <encoding>_<similarity>_<dim>_<density>");
    }
    ScalarEncoding encoding = encodingFor(parts[0]);
    VectorSimilarityFunction similarity = similarityFor(parts[1]);
    int dim = Integer.parseInt(parts[2]);
    boolean dense = parts[3].equals("dense");

    System.out.println("wire_number=" + encoding.getWireNumber());
    System.out.println("doc_packed_length=" + encoding.getDocPackedLength(dim));
    System.out.println("discrete_dimensions=" + encoding.getDiscreteDimensions(dim));

    try (FSDirectory directory = FSDirectory.open(dir)) {
      SegmentInfo segmentInfo =
          new SegmentInfo(
              directory,
              Version.LATEST,
              Version.LATEST,
              "_sq",
              MAX_DOC,
              false,
              false,
              new Lucene104Codec(),
              Collections.emptyMap(),
              SEGMENT_ID.clone(),
              Collections.emptyMap(),
              null);
      FieldInfo info = fieldInfo(dim, similarity);
      FieldInfos fieldInfos = new FieldInfos(new FieldInfo[] {info});
      SegmentWriteState writeState =
          new SegmentWriteState(
              org.apache.lucene.util.InfoStream.NO_OUTPUT,
              directory,
              segmentInfo,
              fieldInfos,
              null,
              IOContext.DEFAULT);

      Lucene104ScalarQuantizedVectorsFormat format =
          new Lucene104ScalarQuantizedVectorsFormat(encoding);
      try (FlatVectorsWriter writer = format.fieldsWriter(writeState)) {
        @SuppressWarnings("unchecked")
        FlatFieldVectorsWriter<float[]> fieldWriter =
            (FlatFieldVectorsWriter<float[]>) writer.addField(info);
        for (int doc = 0; doc < MAX_DOC; doc++) {
          float[] v = vectorFor(doc, dim, dense);
          if (v != null) {
            fieldWriter.addValue(doc, v);
          }
        }
        writer.flush(MAX_DOC, null);
        writer.finish();
      }

      // Merge the segment just written into a second one, so that the bytes
      // `mergeOneFlatVectorField` lays down are compared too. One source
      // segment with no deletions is the shape where the merged view is exactly
      // the source's vectors in order.
      SegmentReadState mergeSourceState =
          new SegmentReadState(directory, segmentInfo, fieldInfos, IOContext.DEFAULT);
      try (FlatVectorsReader source = format.fieldsReader(mergeSourceState)) {
        SegmentInfo mergedInfo =
            new SegmentInfo(
                directory,
                Version.LATEST,
                Version.LATEST,
                "_sqm",
                MAX_DOC,
                false,
                false,
                new Lucene104Codec(),
                Collections.emptyMap(),
                SEGMENT_ID.clone(),
                Collections.emptyMap(),
                null);
        SegmentWriteState mergeState =
            new SegmentWriteState(
                InfoStream.NO_OUTPUT, directory, mergedInfo, fieldInfos, null, IOContext.DEFAULT);
        MergeState ms =
            new MergeState(
                new MergeState.DocMap[] {docID -> docID},
                mergedInfo,
                fieldInfos,
                new org.apache.lucene.codecs.StoredFieldsReader[] {null},
                new org.apache.lucene.codecs.TermVectorsReader[] {null},
                new org.apache.lucene.codecs.NormsProducer[] {null},
                new org.apache.lucene.codecs.DocValuesProducer[] {null},
                new FieldInfos[] {fieldInfos},
                new org.apache.lucene.util.Bits[] {null},
                new org.apache.lucene.codecs.FieldsProducer[] {null},
                new org.apache.lucene.codecs.PointsReader[] {null},
                new org.apache.lucene.codecs.KnnVectorsReader[] {source},
                new int[] {MAX_DOC},
                InfoStream.NO_OUTPUT,
                Runnable::run,
                false,
                null);
        try (FlatVectorsWriter merger = format.fieldsWriter(mergeState)) {
          merger.mergeOneFlatVectorField(info, ms);
          merger.finish();
        }
      }

      // Read the segment back with Lucene's own reader and dump every value, so
      // the Rust side can assert it decodes the same numbers.
      SegmentReadState readState =
          new SegmentReadState(directory, segmentInfo, fieldInfos, IOContext.DEFAULT);
      try (FlatVectorsReader reader = format.fieldsReader(readState)) {
        reader.checkIntegrity();
        System.out.println("ram_bytes_used=" + reader.ramBytesUsed());
        FloatVectorValues values = reader.getFloatVectorValues(FIELD);
        KnnVectorValues.DocIndexIterator it = values.iterator();
        for (int docV = it.nextDoc(); docV != DocIdSetIterator.NO_MORE_DOCS; docV = it.nextDoc()) {
          float[] v = values.vectorValue(it.index());
          StringBuilder sb = new StringBuilder();
          sb.append("vec=").append(docV).append(':').append(it.index()).append(':');
          for (int i = 0; i < v.length; i++) {
            if (i > 0) {
              sb.append(',');
            }
            sb.append(String.format(Locale.ROOT, "%08x", Float.floatToIntBits(v[i])));
          }
          System.out.println(sb);
        }

        // Score a fixed query against every stored vector, through the
        // quantized query path (quantize, transpose for the asymmetric
        // encodings, quantizedScore).
        float[] query = vectorFor(MAX_DOC + 1, dim, true);
        RandomVectorScorer queryScorer = reader.getRandomVectorScorer(FIELD, query);
        for (int ord = 0; ord < queryScorer.maxOrd(); ord++) {
          System.out.println(
              String.format(
                  Locale.ROOT, "score=%d:%08x", ord, Float.floatToIntBits(queryScorer.score(ord))));
        }

        // Score every stored vector against every other one through the
        // merge-time supplier; for an asymmetric encoding this writes the
        // query-width copies into a temporary file first.
        SegmentInfo scoreInfo =
            new SegmentInfo(
                directory,
                Version.LATEST,
                Version.LATEST,
                "_sqs",
                MAX_DOC,
                false,
                false,
                new Lucene104Codec(),
                Collections.emptyMap(),
                SEGMENT_ID.clone(),
                Collections.emptyMap(),
                null);
        SegmentWriteState scoreState =
            new SegmentWriteState(
                InfoStream.NO_OUTPUT, directory, scoreInfo, fieldInfos, null, IOContext.DEFAULT);
        try (CloseableRandomVectorScorerSupplier supplier =
            ((Lucene104ScalarQuantizedVectorsReader) reader)
                .getRandomVectorScorerSupplierForMerge(info, scoreState)) {
          UpdateableRandomVectorScorer mergeScorer = supplier.scorer();
          for (int i = 0; i < supplier.totalVectorCount(); i++) {
            mergeScorer.setScoringOrdinal(i);
            for (int j = 0; j < supplier.totalVectorCount(); j++) {
              System.out.println(
                  String.format(
                      Locale.ROOT,
                      "mergescore=%d:%d:%08x",
                      i,
                      j,
                      Float.floatToIntBits(mergeScorer.score(j))));
            }
          }
        }
      }
    }
    System.out.println("read_ok=true");
  }
}
